     mc("Conversación 2. El hombre no fue a la entrevista porque…", ["no le interesaba el puesto.", "el trabajo implicaba un traslado.", "sus hijos se lo pidieron."], 1),
     mc("Conversación 2. La mujer le reprocha que…", ["no consultara a su familia.", "no le avisara.", "se mudara a Bilbao."], 0),
     mc("Conversación 3. Al hombre la obra le pareció…", ["excesivamente larga.", "mal interpretada.", "perfecta."], 0),
